#!/usr/bin/env node
/**
 * Generates contracts/generated/dforum.<mode>.json from the shared schema.
 *
 * Usage:
 *   node contracts/build.mjs --moderation none|team|network [--deployer <identityId>] [--out <dir>]
 *
 * The schema is written in THIS FILE (and nowhere else) — there is no separate
 * schema file to keep in sync; CI checks that the committed generated files
 * match regeneration.
 *
 * The generated file is committed; CI checks that regeneration is clean.
 *
 * Modes:
 *   none    — no moderation block at all. Nothing removable or bannable at
 *             consensus, ever. Types drop every moderator-only field, index and
 *             moderatorAbilities. Owner mode: settings/categories/forums stay
 *             owner-only (creationRestrictionMode 1).
 *   team    — native moderation, appointed moderators (deployer team). The
 *             roster is edited later via a contract update by the contract
 *             owner.
 *   network — native moderation, elected (masternode-elected team) with an
 *             appointed interim set (the deployer team). Header note: this is
 *             testnet-only and contradicts the brief's non-elected default.
 *
 * Schema notes:
 * - Referenced properties are immutable; required fields are stored and indexed exactly once.
 * - Records keep what the chain returns for moderated deletes (deleteKeepsFields).
 * - Everything is generated by one function per mode; the team contract is committed and
 *   deployed, so keep team output byte-identical to it — schema edits land at next registration.
 * - v3 (2026-11-28, after the contract review): locks and archived forums enforced at consensus
 *   (refersTo where … notEqual const true), moderator flags on post/profile, report audit
 *   index, reactions alert by $updatedAt, replyToId verified, unused indexes and counters dropped,
 *   archive trust can be closed with forumSettings.archiveTrustUntil.
 * - v2 (2026-11-28): archive provenance fields (orig*) on thread/post — trusted only when the
 *   document's $ownerId is forumSettings.archiveOwnerId; sub-forums (forum.parentForumId);
 *   two-part bodies (body + body2, 5120 bytes each); reaction byThread/byRecipient for the
 *   reaction UI and alerts; report.threadId verified by reference; profile not self-deletable;
 *   teamMember deletable; website/avatar patterns; byUpdated/moderated indexes feed the
 *   incremental snapshot.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

const MODERATION_MODES = ['none', 'team', 'network'];


// ---- field schemata --------------------------------------------------------
// "identifier" is the 32-byte identifier shorthand (the same value the chain
// stores for a 32-byte identifier reference).
const ID = { type: 'identifier' };

function string(minLength, maxLength, position, extra = {}) {
  return { type: 'string', minLength, maxLength, ...extra, position };
}
function int(minimum, maximum, position) {
  return { type: 'integer', minimum, ...(maximum === undefined ? {} : { maximum }), position };
}

const slug = (position) => string(1, 48, position, { pattern: '^[a-z0-9-]{1,48}$' });
const title = (position) => string(3, 80, position);
const httpsUrl = (maxLength, position) => string(0, maxLength, position, { pattern: '^(https://\\S+)?$' });
const BODY_MAX_BYTES = 5120;

/** Archive provenance (backfill). Anyone may write these fields; readers trust them only when
 * the document's $ownerId equals forumSettings.archiveOwnerId (an owner-only setting). */
function archiveProps(cursor) {
  return {
    origId: int(1, undefined, cursor()),
    origAuthor: string(1, 50, cursor()),
    origAuthorId: int(0, undefined, cursor()),
    // Milliseconds since the epoch.
    origCreatedAt: int(0, undefined, cursor()),
  };
}

/** Importer idempotency: document ids include the create nonce, so a retried create would
 * otherwise duplicate. Live documents have no origId and are skipped. */
const BY_ORIGIN = { name: 'byOrigin', properties: [{ $ownerId: 'asc' }, { origId: 'asc' }], unique: true, skipIfAbsent: ['origId'] };

// Archived forums take no new threads or posts: the reference refuses them at consensus. (A
// notEqual against a constant holds while the field is absent.)
const NOT_TRUE = { notEqual: { const: true } };
const FORUM_ID = {
  type: 'identifier',
  refersTo: { type: 'permanentDocument', documentType: 'forum', where: { archived: NOT_TRUE } },
};
const THREAD_ID = (moderated) => ({
  type: 'identifier',
  refersTo: {
    // The platform refuses a moderatedDocument reference to a thread with no
    // moderatorAbilities — none mode is a permanent reference.
    type: moderated ? 'moderatedDocument' : 'permanentDocument',
    documentType: 'thread',
    // A locked thread refuses new posts at consensus (moderated modes only have `locked`).
    where: moderated ? { forumId: 'forumId', locked: NOT_TRUE } : { forumId: 'forumId' },
  },
});
const FORUM_REF_REQUIRED = ['$createdAt', '$updatedAt', 'forumId', 'title'];

// Archive provenance can't change after creation, so closing the trust window (or a leaked archivist
// key) can't rewrite who wrote an imported post or when.
const ARCHIVE_IMMUTABLE = ['origId', 'origAuthor', 'origAuthorId', 'origCreatedAt'];

// A reference is re-checked on replace only when a rule reads through it. This rule makes every
// create and every edit read the thread, so a lock freezes existing posts and reactions too.
// (Booleans read as 1/0 in rules; a moderator-deleted thread keeps `locked`.)
const THREAD_OPEN = { threadOpen: { equal: [{ ifAbsent: [{ referenced: ['threadId', 'locked'] }, 0] }, 0] } };
const WHEN_LOCKED = { equal: ['$old.locked', 1] };

// ---- document types ----------------------------------------------------------

function forumSettingsType() {
  let positionCursor = 0;
  return {
    type: 'object',
    canBeDeleted: false,
    creationRestrictionMode: 1,
    documentsMutable: true,
    properties: {
      key: { ...string(1, 16, positionCursor++, { pattern: '^[a-z0-9-]{1,16}$' }) },
      name: string(1, 80, positionCursor++),
      tagline: string(0, 160, positionCursor++),
      description: string(0, 1000, positionCursor++),
      rules: string(0, 4000, positionCursor++, { maxBytes: BODY_MAX_BYTES }),
      announcement: string(0, 500, positionCursor++),
      archiveOwnerId: { type: 'identifier', position: positionCursor++ },
      archiveSourceName: string(0, 80, positionCursor++),
      archiveSourceUrl: httpsUrl(200, positionCursor++),
      // Milliseconds: archive provenance is trusted only on documents created before this, so the
      // archivist can be retired without withdrawing trust from what it already imported.
      archiveTrustUntil: int(0, undefined, positionCursor++),
    },
    required: ['$createdAt', 'key', 'name'],
    additionalProperties: false,
    indices: [
      { name: 'byKey', properties: [{ key: 'asc' }], unique: true },
    ],
  };
}

function categoryType() {
  let positionCursor = 0;
  return {
    type: 'object',
    canBeDeleted: false,
    creationRestrictionMode: 1,
    documentsMutable: true,
    immutable: ['slug'],
    properties: {
      slug: slug(positionCursor++),
      title: title(positionCursor++),
      description: string(0, 300, positionCursor++),
      sort: int(0, 65535, positionCursor++),
    },
    required: ['$createdAt', 'slug', 'title', 'sort'],
    additionalProperties: false,
    indices: [
      { name: 'bySlug', properties: [{ slug: 'asc' }], unique: true },
      { name: 'bySort', properties: [{ sort: 'asc' }] },
    ],
  };
}

function forumType() {
  let positionCursor = 0;
  return {
    type: 'object',
    canBeDeleted: false,
    creationRestrictionMode: 1,
    documentsMutable: true,
    immutable: ['slug'],
    properties: {
      // Owner-only type, so plain identifiers are trusted and stay movable; readers ignore a
      // category or parent that is missing, and a parent that would form a cycle.
      categoryId: { type: 'identifier', position: positionCursor++ },
      parentForumId: { type: 'identifier', position: positionCursor++ },
      slug: slug(positionCursor++),
      title: title(positionCursor++),
      description: string(0, 500, positionCursor++),
      sort: int(0, 65535, positionCursor++),
      archived: { type: 'boolean', position: positionCursor++ },
      origId: int(1, undefined, positionCursor++),
    },
    required: ['$createdAt', 'categoryId', 'slug', 'title', 'sort'],
    additionalProperties: false,
    indices: [
      { name: 'bySlug', properties: [{ slug: 'asc' }], unique: true },
      { name: 'byCategory', properties: [{ categoryId: 'asc' }, { sort: 'asc' }] },
    ],
  };
}

function teamMemberType() {
  let positionCursor = 0;
  return {
    type: 'object',
    canBeDeleted: true,
    creationRestrictionMode: 1,
    documentsMutable: true,
    properties: {
      memberId: { type: 'identifier', position: positionCursor++ },
      role: string(1, 40, positionCursor++),
      sort: int(0, 65535, positionCursor++),
    },
    required: ['$createdAt', 'memberId', 'role', 'sort'],
    additionalProperties: false,
    indices: [
      { name: 'byMember', properties: [{ memberId: 'asc' }], unique: true },
    ],
  };
}

function threadType(mode) {
  let positionCursor = 0;
  const moderated = mode !== 'none';
  const props = {
    forumId: { ...FORUM_ID, position: positionCursor++ },
    title: string(3, 150, positionCursor++),
    tags: {
      type: 'array',
      minItems: 0,
      maxItems: 5,
      uniqueItems: true,
      items: { type: 'string', minLength: 1, maxLength: 32, pattern: '^[a-z0-9-]{1,32}$' },
      position: positionCursor++,
    },
    ...archiveProps(() => positionCursor++),
  };
  if (moderated) {
    props.sticky = { type: 'boolean', position: positionCursor++ };
    props.locked = { type: 'boolean', position: positionCursor++ };
    props.modState = int(1, 3, positionCursor++);
    props.modNote = string(0, 200, positionCursor++);
    // forumId is referenced and immutable; a moderator move re-homes the thread for readers.
    props.movedToForumId = { type: 'identifier', position: positionCursor++ };
    // Spare moderator-only bit field (featured, solved, …): changeFields cannot grow later.
    props.modFlags = int(0, 65535, positionCursor++);
  }
  // Listings come from the snapshot; these indexes serve the live paths and the snapshot's deltas.
  const indices = [
    { name: 'byForum', properties: [{ forumId: 'asc' }, { $createdAt: 'asc' }] },
    { name: 'byAuthor', properties: [{ $ownerId: 'asc' }, { $createdAt: 'asc' }] },
    { name: 'byUpdated', properties: [{ $updatedAt: 'asc' }] },
    BY_ORIGIN,
  ];
  if (moderated) {
    indices.push({ name: 'moderated', properties: [{ $moderatedAt: 'asc' }], nullSearchable: false });
  }
  return {
    type: 'object',
    canBeDeleted: false,
    documentsMutable: true,
    // A locked thread's title and tags are frozen along with its posts.
    immutable: ['forumId', ...ARCHIVE_IMMUTABLE, ...(moderated ? [{ property: 'title', when: WHEN_LOCKED }, { property: 'tags', when: WHEN_LOCKED }] : [])],
    ...(moderated
      ? { moderatorAbilities: { delete: true, deleteKeepsFields: ['forumId', 'locked', 'origId'], changeFields: ['sticky', 'locked', 'modState', 'modNote', 'movedToForumId', 'modFlags'] } }
      : {}),
    properties: props,
    required: FORUM_REF_REQUIRED,
    additionalProperties: false,
    indices,
  };
}

/** Posts are never author-deletable: moderated mode can still remove them (moderatedDocument),
 * none mode cannot remove them at all (permanentDocument). */
const postRefKind = (mode) => (mode === 'none' ? 'permanentDocument' : 'moderatedDocument');

function postType(mode) {
  let positionCursor = 0;
  const moderated = mode !== 'none';
  const props = {
    threadId: { ...THREAD_ID(moderated), position: positionCursor++ },
    forumId: { ...FORUM_ID, position: positionCursor++ },
    body: string(1, BODY_MAX_BYTES, positionCursor++, { maxBytes: BODY_MAX_BYTES }),
    body2: string(1, BODY_MAX_BYTES, positionCursor++, { maxBytes: BODY_MAX_BYTES }),
    replyToId: {
      type: 'identifier',
      refersTo: { type: postRefKind(mode), documentType: 'post', where: { threadId: 'threadId' } },
      position: positionCursor++,
    },
    // Author delete is a tombstone replace (posts are not deletable), so the byUpdated delta
    // sees it; readers suppress the body.
    retracted: { type: 'boolean', position: positionCursor++ },
    ...archiveProps(() => positionCursor++),
  };
  if (moderated) {
    props.modState = int(1, 3, positionCursor++);
    props.modNote = string(0, 200, positionCursor++);
    props.modFlags = int(0, 65535, positionCursor++);
  }
  const indices = [
    { name: 'byThread', properties: [{ threadId: 'asc' }, { $createdAt: 'asc' }] },
    { name: 'byAuthor', properties: [{ $ownerId: 'asc' }, { $createdAt: 'asc' }] },
    { name: 'byUpdated', properties: [{ $updatedAt: 'asc' }] },
    BY_ORIGIN,
  ];
  if (moderated) {
    indices.push({ name: 'moderated', properties: [{ $moderatedAt: 'asc' }], nullSearchable: false });
  }
  return {
    type: 'object',
    canBeDeleted: false,
    documentsMutable: true,
    immutable: ['threadId', 'forumId', 'replyToId', ...ARCHIVE_IMMUTABLE],
    ...(moderated
      ? {
        // origId survives a moderator delete so a re-run importer can tell a removed post from a missing one.
        moderatorAbilities: { delete: true, deleteKeepsFields: ['threadId', 'forumId', 'origId'], changeFields: ['modState', 'modNote', 'modFlags'] },
        propertyConstraints: THREAD_OPEN,
      }
      : {}),
    properties: props,
    required: ['$createdAt', '$updatedAt', 'threadId', 'forumId', 'body'],
    additionalProperties: false,
    indices,
  };
}

function reactionType(mode) {
  let positionCursor = 0;
  const moderated = mode !== 'none';
  return {
    type: 'object',
    // Un-reacting replaces kind with 0 instead of deleting, so every change moves $updatedAt and
    // the byUpdated delta (snapshot + live overlay) sees it; the unique byPostOwner key keeps one
    // row per (post, reactor).
    canBeDeleted: false,
    documentsMutable: true,
    immutable: ['postId', 'postOwnerId', 'threadId'],
    properties: {
      postId: {
        type: 'identifier',
        refersTo: {
          type: postRefKind(mode),
          documentType: 'post',
          where: { $ownerId: 'postOwnerId', threadId: 'threadId' },
        },
        position: positionCursor++,
      },
      postOwnerId: { type: 'identifier', position: positionCursor++ },
      threadId: moderated
        ? { ...THREAD_ID(true), refersTo: { type: 'moderatedDocument', documentType: 'thread', where: { locked: NOT_TRUE } }, position: positionCursor++ }
        : { type: 'identifier', position: positionCursor++ },
      kind: int(0, 63, positionCursor++),
    },
    // No reacting to your own posts; in moderated modes a lock also freezes reaction toggles.
    propertyConstraints: { notSelf: { notEqual: ['postOwnerId', '$ownerId'] }, ...(moderated ? THREAD_OPEN : {}) },
    required: ['$createdAt', '$updatedAt', 'postId', 'postOwnerId', 'threadId', 'kind'],
    additionalProperties: false,
    indices: [
      { name: 'byPostOwner', properties: [{ postId: 'asc' }, { $ownerId: 'asc' }], unique: true },
      { name: 'byThread', properties: [{ threadId: 'asc' }, { $createdAt: 'asc' }] },
      // Reactions toggle in place, so alerts order by the latest change.
      { name: 'byRecipient', properties: [{ postOwnerId: 'asc' }, { $updatedAt: 'asc' }] },
      { name: 'byUpdated', properties: [{ $updatedAt: 'asc' }] },
    ],
  };
}

function reportType(mode) {
  let positionCursor = 0;
  const moderated = mode !== 'none';
  const props = {
    postId: {
      type: 'identifier',
      refersTo: { type: postRefKind(mode), documentType: 'post', where: { threadId: 'threadId' } },
      position: positionCursor++,
    },
    threadId: { type: 'identifier', position: positionCursor++ },
    reason: int(1, 8, positionCursor++),
    note: string(0, 280, positionCursor++),
  };
  const required = ['$createdAt', 'postId', 'threadId', 'reason'];
  if (moderated) {
    props.status = int(1, 3, positionCursor++);
    props.resolution = string(0, 200, positionCursor++);
  }
  const indices = [
    { name: 'byPostReporter', properties: [{ postId: 'asc' }, { $ownerId: 'asc' }], unique: true },
    { name: 'recent', properties: [{ $createdAt: 'asc' }] },
  ];
  // Resolved reports carry $moderatedAt: the queue subtracts them, the audit log lists them.
  if (moderated) indices.push({ name: 'moderated', properties: [{ $moderatedAt: 'asc' }], nullSearchable: false });
  return {
    type: 'object',
    // A reporter can't withdraw and refile a dismissed report to put it back in the queue.
    canBeDeleted: false,
    documentsMutable: false,
    ...(moderated ? { moderatorAbilities: { delete: true, changeFields: ['status', 'resolution'] } } : {}),
    properties: props,
    required,
    additionalProperties: false,
    indices,
  };
}

function profileType(mode) {
  let positionCursor = 0;
  const moderated = mode !== 'none';
  const props = {
    // No control, zero-width or bidi-override characters (they let a name impersonate another).
    displayName: string(1, 40, positionCursor++, { pattern: '^[^\\x00-\\x1F\\x7F\\x{200B}-\\x{200F}\\x{202A}-\\x{202E}\\x{2066}-\\x{2069}\\x{FEFF}]+$' }),
    bio: string(0, 1000, positionCursor++),
    signature: string(0, 300, positionCursor++),
    avatarUrl: httpsUrl(300, positionCursor++),
    website: string(0, 200, positionCursor++, { pattern: '^(https?://\\S+)?$' }),
    location: string(0, 60, positionCursor++),
  };
  if (moderated) {
    props.customTitle = string(0, 40, positionCursor++);
    props.modState = int(1, 3, positionCursor++);
    props.modFlags = int(0, 65535, positionCursor++);
  }
  const indices = [
    { name: 'byOwner', properties: [{ $ownerId: 'asc' }], unique: true },
    { name: 'byUpdated', properties: [{ $updatedAt: 'asc' }] },
  ];
  if (moderated) {
    indices.push({ name: 'moderated', properties: [{ $moderatedAt: 'asc' }], nullSearchable: false });
  }
  return {
    type: 'object',
    // A profile is the identity's public face: the owner edits it but cannot erase it (a hidden
    // profile must not be deletable and re-creatable).
    canBeDeleted: false,
    documentsMutable: true,
    ...(moderated ? { moderatorAbilities: { delete: true, changeFields: ['customTitle', 'modState', 'modFlags'] } } : {}),
    properties: props,
    required: ['$createdAt', '$updatedAt', 'displayName'],
    additionalProperties: false,
    indices,
  };
}


// ---- static reference check (mirrors the platform's document_reference_kind) ----
// permanentDocument: the target can't be deleted, has no moderator delete, no ttl.
// moderatedDocument: only moderators can delete the target, and the record is kept.
// deletableDocument: everything else.
function referenceKindFor(target) {
  if (target.canBeDeleted === false && !target.moderatorAbilities?.delete && target.ttl === undefined) {
    return 'permanentDocument';
  }
  if (target.canBeDeleted === false && target.moderatorAbilities?.delete) {
    return 'moderatedDocument';
  }
  return 'deletableDocument';
}

export function validateReferences(documentSchemas) {
  for (const [name, schema] of Object.entries(documentSchemas)) {
    for (const [propName, prop] of Object.entries(schema.properties ?? {})) {
      const ref = prop.refersTo;
      if (!ref) continue;
      const target = documentSchemas[ref.documentType];
      if (!target) throw new Error(`${name}.${propName}: refersTo unknown documentType '${ref.documentType}'`);
      const allowed = referenceKindFor(target);
      if (ref.type !== allowed) {
        throw new Error(`${name}.${propName}: refersTo '${ref.type}' but '${ref.documentType}' must be '${allowed}'`);
      }
    }
  }
}

// ---- assembly ---------------------------------------------------------------

function moderatorsFor(mode, deployer) {
  if (mode === 'team') {
    if (!deployer) throw new Error('team mode requires --deployer <identityId>: the appointed moderator set must be non-empty (an appointedModerators config with an empty set is refused). The deployer is the initial moderator; add team members later with a contract update.');
    return { $type: 'appointedModerators', identities: [deployer] };
  }
  if (mode === 'network') {
    // Intentionally fixed for testnet: elected moderators with a locked seat
    // (no contest, no additions beyond the owner) and the deployer as the
    // interim appointed set. A production network deployment is a separate,
    // explicitly reviewed decision — not the default.
    if (!deployer) throw new Error('network mode requires --deployer <identityId> for the interim appointed set');
    return {
      $type: 'elected',
      seatContestable: false,
      maxAddedModerators: 0,
      ownerProtected: true,
      // Identity actions need the lists the contract keeps (banlist/
      // suspensions/warnings are true above) — a charter claiming them on
      // these types can ban, suspend and warn identities.
      moderatedDocumentTypes: {
        thread: ['deleteDocuments', 'changeDocumentFields', 'ban', 'suspend', 'warn'],
        post: ['deleteDocuments', 'changeDocumentFields', 'ban', 'suspend', 'warn'],
        report: ['deleteDocuments', 'changeDocumentFields', 'ban', 'suspend', 'warn'],
        profile: ['deleteDocuments', 'changeDocumentFields', 'ban', 'suspend', 'warn'],
      },
      interim: { $type: 'appointedModerators', identities: [deployer] },
    };
  }
  return null;
}

export function buildContract({ moderation = 'team', deployer = null }) {
  if (!MODERATION_MODES.includes(moderation)) {
    throw new Error(`--moderation must be one of ${MODERATION_MODES.join('|')}`);
  }
  const moderated = moderation !== 'none';

  const documentSchemas = {
    forumSettings: forumSettingsType(),
    category: categoryType(),
    forum: forumType(),
    teamMember: teamMemberType(),
    thread: threadType(moderation),
    post: postType(moderation),
    reaction: reactionType(moderation),
    report: reportType(moderation),
    profile: profileType(moderation),
  };

  const config = {
    $formatVersion: '2',
    canBeDeleted: false,
    readonly: false,
    keepsHistory: false,
    documentsKeepHistoryContractDefault: false,
    documentsMutableContractDefault: true,
    documentsCanBeDeletedContractDefault: true,
    sizedIntegerTypes: true,
  };
  if (moderated) {
    config.moderation = {
      banlist: true,
      suspensions: true,
      warnings: true,
      moderators: moderatorsFor(moderation, deployer),
    };
  }

  validateReferences(documentSchemas);

  return {
    $formatVersion: '1',
    id: 'PV5ERAp8YpWhfpG2K8kEYoCEshKM2VgkY4UQyUQCUMCc',
    ownerId: 'PV5ERAp8YpWhfpG2K8kEYoCEshKM2VgkY4UQyUQCUMCc',
    version: 1,
    description: moderation === 'none'
      ? 'dForum: a forum on Dash Platform, unmoderated (nothing removable at consensus).'
      : moderation === 'network'
        ? 'dForum: a forum on Dash Platform, elected moderation (testnet only, not for production).'
        : 'dForum v4: a forum on Dash Platform, owned and moderated by the deployer team.',
    config,
    documentSchemas,
    keywords: ['forum', 'community', 'dash-platform'],
  };
}

// ---- CLI -------------------------------------------------------------------

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const args = process.argv.slice(2);
  let mode = 'team';
  let deployer = null;
  let outDir = join(REPO_ROOT, 'contracts', 'generated');
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--moderation') mode = args[++i];
    else if (args[i] === '--deployer') deployer = args[++i];
    else if (args[i] === '--out') outDir = args[++i];
    else if (args[i] === '--help' || args[i] === '-h') {
      console.log('Usage: node contracts/build.mjs --moderation none|team|network [--deployer <identityId>] [--out <dir>]');
      process.exit(0);
    } else throw new Error(`unknown argument: ${args[i]}`);
  }
  const contract = buildContract({ moderation: mode, deployer });
  mkdirSync(outDir, { recursive: true });
  const outFile = join(outDir, `dforum.${mode}.json`);
  writeFileSync(outFile, JSON.stringify(contract, null, 2) + '\n');
  console.log(`wrote ${outFile}`);
}
